const gl_bridge_decl *gl_bridge_lookup(const char *name);
int gl_bridge_count(void);

const gl_bridge_decl *gl_bridge_lookup(const char *name)
{
    int lo = 0, hi = (int)(sizeof GL_DECLS / sizeof GL_DECLS[0]) - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        int r = __builtin_strcmp(name, GL_DECLS[mid].name);
        if (r == 0) return &GL_DECLS[mid];
        if (r < 0) hi = mid - 1; else lo = mid + 1;
    }
    return 0;
}
int gl_bridge_count(void) { return (int)(sizeof GL_DECLS / sizeof GL_DECLS[0]); }
